def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    sep_rows = [
        r for r in range(h)
        if len(set(grid[r])) == 1 and grid[r][0] != background
    ]
    sep_cols = [
        c for c in range(w)
        if len({grid[r][c] for r in range(h)}) == 1
        and grid[0][c] != background
    ]

    def segments(length, separators):
        bounds = [-1] + separators + [length]
        return [
            (bounds[i] + 1, bounds[i + 1])
            for i in range(len(bounds) - 1)
            if bounds[i] + 1 < bounds[i + 1]
        ]

    row_segments = segments(h, sep_rows)
    col_segments = segments(w, sep_cols)
    if not row_segments or not col_segments:
        return [row[:] for row in grid]

    # Select the compartment containing the most non-background pattern cells.
    best = None
    for r0, r1 in row_segments:
        for c0, c1 in col_segments:
            count = sum(
                grid[r][c] != background
                for r in range(r0, r1)
                for c in range(c0, c1)
            )
            if best is None or count > best[0]:
                best = (count, r0, r1, c0, c1)

    _, sr0, sr1, sc0, sc1 = best
    tile = [row[sc0:sc1] for row in grid[sr0:sr1]]
    th, tw = len(tile), len(tile[0])
    out = [row[:] for row in grid]

    for r0, r1 in row_segments:
        for c0, c1 in col_segments:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = tile[(r - r0) % th][(c - c0) % tw]

    return out
